from math import gcd
from collections import deque
from fractions import Fraction

def solve_problem():
    # We search pairs (m, n) such that m < n, gcd(m, n) = 1, and m + n <= 50.
    # The problem is symmetric (m/n and n/m are the starting numbers).

    pairs_to_check = []
    for m in range(1, 50):
        for n in range(m + 1, 51):
            if gcd(m, n) == 1:
                pairs_to_check.append((m, n))

    print(f"Checking {len(pairs_to_check)} coprime pairs.")

    results = {}
    MAX_STEPS = 10

    for m, n in pairs_to_check:
        # Initial numbers are x0 = m/n and y0 = n/m.
        # Using Fraction ensures exact arithmetic.
        start_numbers = {Fraction(m, n), Fraction(n, m)}

        # BFS structure: queue holds (set_of_numbers, step_count)
        queue = deque([(start_numbers, 0)])
        visited_states = {frozenset(start_numbers)}

        found = False

        while queue:
            current_set, steps = queue.popleft()

            if steps >= MAX_STEPS:
                continue

            # Check if 1 is already present
            if Fraction(1) in current_set:
                found = True
                break

            numbers = list(current_set)
            L = len(numbers)

            # Try applying AM and HM to every pair (x, y) in the current set
            for i in range(L):
                for j in range(i + 1, L):
                    x = numbers[i]
                    y = numbers[j]

                    # 1. Arithmetic Mean (AM)
                    am = (x + y) / 2

                    # 2. Harmonic Mean (HM)
                    # HM = 2xy / (x + y)
                    if x + y != 0:
                        hm = (2 * x * y) / (x + y)
                    else:
                        hm = None # Should not happen since m, n > 0

                    if am is not None:
                        next_set_am = current_set.union({am})
                        frozen_set_am = frozenset(next_set_am)
                        if frozen_set_am not in visited_states:
                            if Fraction(1) in next_set_am:
                                found = True
                                break
                            visited_states.add(frozen_set_am)
                            queue.append((next_set_am, steps + 1))

                    if hm is not None:
                        next_set_hm = current_set.union({hm})
                        frozen_set_hm = frozenset(next_set_hm)
                        if frozen_set_hm not in visited_states:
                            if Fraction(1) in next_set_hm:
                                found = True
                                break
                            visited_states.add(frozen_set_hm)
                            queue.append((next_set_hm, steps + 1))
                if found:
                    break

